// ChatInput.js
import React, { useState, useRef } from "react";

export default function ChatInput({ onSend, onUpload, loading, areasHint = [], fileHint = "" }) {
  const [text, setText] = useState("");
  const [file, setFile] = useState(null);
  const inputRef = useRef();

  const submit = (e) => {
    e?.preventDefault();
    if (!text.trim()) return;
    onSend(text.trim());
    setText("");
  };

  const onFileChange = (ev) => {
    const f = ev.target.files?.[0];
    setFile(f);
  };

  const upload = async () => {
    if (!file) return alert("Choose an Excel file (.xlsx)");
    await onUpload(file);
    setFile(null);
    if (inputRef.current) inputRef.current.value = "";
  };

  return (
    <div>
      <form onSubmit={submit} className="d-flex gap-2">
        <textarea
          ref={inputRef}
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder='Try: "Analyze Wakad"'
          className="form-control"
          rows={1}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              submit();
            }
          }}
          disabled={loading}
        />
        <button className="btn btn-primary" type="submit" disabled={loading || !text.trim()}>Send</button>
      </form>

      <div className="d-flex align-items-center gap-2 mt-2">
        <input ref={inputRef} id="file-input" type="file" accept=".xlsx" onChange={onFileChange} className="form-control form-control-sm" />
        <button className="btn btn-secondary btn-sm" onClick={upload} disabled={loading || !file}>Upload Excel</button>
      </div>

      <div className="mt-2">
        {fileHint && <div className="text-warning small">{fileHint}</div>}
        {areasHint && areasHint.length > 0 && <div className="small text-muted">Known areas: {areasHint.slice(0,8).join(", ")}{areasHint.length > 8 ? ", ..." : ""}</div>}
      </div>
    </div>
  );
}
